SELECT count(*) FROM plate_material_effect
 WHERE tenant_id = #{t}
   AND source_run_id = #{runId}
   AND status IN ('PENDING','FAILED','REJECTED','NEEDS_RECONCILIATION')

SELECT
    (SELECT count(*) FROM plate_material_effect
      WHERE tenant_id = #{t} AND source_run_id = #{runId}
        AND source_node_key IN
        #{k}
        AND status IN ('PENDING','FAILED','REJECTED','NEEDS_RECONCILIATION'))
  + (SELECT count(*) FROM run_node
      WHERE tenant_id = #{t} AND run_id = #{runId}
        AND level = 0 AND loop_index = 0
        AND node_key IN
        #{k}
        AND execution_resolution_status = 'reconciliation_required')

SELECT state_version FROM plate
 WHERE tenant_id = #{t} AND id = #{plateId}
 LIMIT 1

SELECT id FROM plate_material_effect
 WHERE tenant_id = #{t} AND plate_id = #{plateId}
   AND status = 'PENDING'
   AND expected_state_version <> #{newVersion}

SELECT id, source_run_id AS "runId", source_node_key AS "nodeKey",
       source_loop_index AS "loopIndex", plate_id AS "plateId", status,
       expected_process_state AS "processState", expected_seal_state AS "sealState",
       last_error_code AS "lastErrorCode", updated_at AS "updatedAt"
  FROM plate_material_effect
 WHERE tenant_id = #{t}
 AND status = #{status} 
 AND source_run_id = #{runId} 
 AND plate_id = #{plateId} 
 ORDER BY id DESC LIMIT 200

SELECT p.barcode AS "barcode", p.plate_type AS "plateType",
       p.process_state AS "processState", p.seal_state AS "sealState",
       p.state_version AS "stateVersion", p.position_status AS "positionStatus",
       p.status AS "status", p.location_id AS "locationId",

       to_char(p.updated_at AT TIME ZONE 'UTC',
               'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "updatedAt"
  FROM plate p
 WHERE p.tenant_id = #{t} AND p.deleted_at IS NULL

   AND p.process_state = #{processState}


   AND p.plate_type = #{plateType}


   AND p.position_status = #{positionStatus}

 ORDER BY p.id DESC
 LIMIT #{limit}

SELECT id FROM plate_material_effect
 WHERE tenant_id = #{t}
   AND source_run_id = #{runId}
   AND source_node_key = #{nodeKey}
   AND source_loop_index = #{loopIndex}
   AND effect_index = #{effectIndex}
 LIMIT 1

